-- ㉠ R2 가 실행 → 오류
SELECT * FROM T;
-- R1 이 실행
GRANT SELECT ON T TO R2;
-- ㉡ R2 가 실행
SELECT * FROM T;
-- ㉢ R2 가 실행
SELECT * FROM R1.T;
-- R2 가 실행
CREATE SYNONYM T FOR R1.T;
-- ㉣ R2 가 실행
SELECT * FROM T;

-- ㉠
SELECT * FROM T WHERE ROWNUM IN (1, 2);
-- ㉡
SELECT * FROM T WHERE ROWNUM IN (2, 3);
-- ㉢
SELECT * FROM T WHERE ROWNUM < 1;
-- ㉣
SELECT * FROM T WHERE ROWNUM <> 2;

