-- ㉠
SELECT COUNT(*) FROM A, B;
-- ㉡
SELECT COUNT(*)
FROM   A LEFT OUTER JOIN B
       ON 1 = 1;
-- ㉢
SELECT COUNT(*)
FROM   A, (SELECT COUNT(*) AS CNT
           FROM   B) V;

